      content: '<strong>bold</strong>',
    });
    expect(html).toContain('&lt;script&gt;');
    expect(html).toContain('<strong>bold</strong>');
  });

  it('exports the default layout source', () => {
    expect(DEFAULT_LAYOUT_SOURCE).toContain('{{{body}}}');
  });
});

